608	            : new Evaluator.ContainsWholeText(searchText);
609	    }
610	
611	    // pseudo selector :containsData(data)
612	    private Evaluator containsData() {
613	        String searchText = TokenQueue.unescape(consumeParens());
614	        Validate.notEmpty(searchText, ":containsData(text) query must not be empty");
615	        return new Evaluator.ContainsData(searchText);
616	    }
617	
618	    // :matches(regex), matchesOwn(regex)
619	    private Evaluator matches(boolean own) {
620	        String query = own ? ":matchesOwn" : ":matches";
621	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
622	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
623	        Regex pattern = Regex.compile(regex);
624	
625	        if (inNodeContext)
626	            return new NodeEvaluator.MatchesValue(pattern);
627	
628	        return own
629	            ? new Evaluator.MatchesOwn(pattern)
630	            : new Evaluator.Matches(pattern);
631	    }
632	
633	    // :matches(regex), matchesOwn(regex)
634	    private Evaluator matchesWholeText(boolean own) {
635	        String query = own ? ":matchesWholeOwnText" : ":matchesWholeText";
636	        String regex = consumeParens(); // don't unescape, as regex bits will be escaped
637	        Validate.notEmpty(regex, query + "(regex) query must not be empty");
638	
