/**
 * Evaluator for matching elements by their language, per the CSS {@code :lang()} pseudo-class. The element's
 * language is its own {@code lang} attribute, or the nearest inherited {@code lang} from an ancestor. An empty
 * {@code lang} value means the language is unknown and blocks inheritance. Matches when the element's language
 * equals the range, or starts with the range followed by a {@code -} (ASCII case-insensitive).
 */
public static final class Lang extends Evaluator {
    private final String range;

    public Lang(String range) {
        this.range = range;
    }

    @Override
    public boolean matches(Element root, Element element) {
        String lang = null;
        for (Element el = element; el != null; el = el.parent()) {
            if (el.hasAttr("lang")) {
                lang = el.attr("lang");
                break; // an empty value means the language is unknown, and does not inherit further
            }
        }
        if (lang == null || lang.isEmpty()) return false;

        int len = range.length();
        if (lang.length() < len) return false;
        if (lang.length() > len && lang.charAt(len) != '-') return false;
        for (int i = 0; i < len; i++) {
            if (asciiLower(lang.charAt(i)) != asciiLower(range.charAt(i))) return false;
        }
        return true;
    }

    private static char asciiLower(char c) {
        return c >= 'A' && c <= 'Z' ? (char) (c + 32) : c;
    }

    @Override
    public String toString() {
        return ":lang(" + range + ")";
    }
}
```

