    assertSelectedIds(doc.select(":lang(en)"), "m", "a", "b", "c");
    assertSelectedIds(doc.select(":lang(en-US)"), "b", "c");
    assertSelectedIds(doc.select(":lang(enough)"), "d"); // ASCII case-insensitive, and "en" does not prefix-match "ENough"

    // quoted and padded forms are equivalent
    assertSelectedIds(doc.select(":lang( 'en-US' )"), "b", "c");
    assertSelectedIds(doc.select(":lang(\"EN-us\")"), "b", "c");

    // combines with other selectors, stays in document order without duplicates
